.catalog-groups li {
  padding: 0;
}
.catalog-groups button {
  padding: 7px 8px;
}
.panel-heading {
  padding: 24px 22px 18px;
}
.palette-footer {
  padding: 16px;
}
@media (max-width: 900px) {
  .workspace {
    position: relative;
    padding-top: 44px;
  }
  .panel-switches {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    display: flex;
    gap: 8px;
    padding: 7px 12px;
    border-bottom: 1px solid #dce3ed;
    background: #fff;
    z-index: 12;
    height: 44px;
  }
  .panel-switches button {
    border: 1px solid #c5cfe0;
    border-radius: 6px;
    background: white;
    padding: 4px 12px;
    color: #34445e;
    font-size: 12px;
  }
  .panel-switches button[aria-expanded="true"] {
    background: #edf0ff;
    border-color: #5362de;
  }
  .workspace > .palette,
  .workspace > .inspector {
    display: none;
    position: absolute;
    top: 44px;
    bottom: 0;
    width: 260px;
    z-index: 11;
    box-shadow: 0 10px 25px #23304722;
  }
  .workspace > .palette {
    left: 0;
  }
  .workspace > .inspector {
    right: 0;
  }
  .panel-components > .palette {
    display: flex;
  }
  .panel-properties > .inspector {
    display: block;
  }
  .editor-toolbar {
    flex-wrap: wrap;
  }
  .canvas {
    min-height: 180px;
  }
  .file-actions {
    margin-left: 0;
  }
  .canvas-footer {
    padding: 10px 12px;
  }
}

aside[inert] { opacity: .55; }
.editor-toolbar .cleanup-status { width: auto; height: auto; background: none; font-size: 12px; color: #536579; }
dialog.lesson-dialog { width: min(720px, calc(100vw - 32px)); max-height: calc(100dvh - 32px); padding: 24px; box-sizing: border-box; overflow: auto; }
dialog.lesson-dialog::backdrop { background: rgb(18 24 35 / 65%); }
.lesson-dialog h2 { padding-right: 40px; font-size: 18px; }
.lesson-close { position: absolute; right: 16px; top: 16px; }
.lesson-body { min-height: 320px; }
.lesson-body h3 { font-size: 24px; line-height: 1.25; margin: 12px 0 20px; }
.lesson-dialog .lesson-body p { line-height: 1.6; font-size: 16px; color: #30394a; }
.lesson-dialog h3 { text-transform: none; letter-spacing: 0; }
.lesson-body small { color: #495acb; font-weight: 700; }
.lesson-diagram { margin: 24px 0; padding: 24px 0; border-block: 1px solid #e5e9f0; }
.lesson-exchange { display: grid; grid-template-columns: minmax(0, 1fr) minmax(90px, 1fr) minmax(0, 1fr); gap: 12px; align-items: center; }
.lesson-node { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; min-height: 84px; padding: 12px 6px; border: 1px solid #dce3ee; border-radius: 8px; background: #f8fafc; color: #303c50; font-size: 13px; font-weight: 500; text-align: center; }
.lesson-node > svg { width: 22px; height: 22px; color: #5361cb; }
.lesson-node small { font-size: 11px; font-weight: 400; color: #64748b; }
.lesson-node small:empty { display: none; }
.lesson-messages { display: grid; justify-items: center; gap: 4px; font-size: 12px; color: #4c5c75; }
.lesson-messages > svg { width: 100%; height: 20px; stroke-width: 1.5; }
.lesson-messages > span:nth-of-type(2) { margin-top: 10px; }
.lesson-storage { width: calc((100% - 24px) / 3); margin-left: auto; text-align: center; }
.lesson-storage > svg { margin: 8px auto; }
.lesson-variants { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
.lesson-variants h4 { margin: 0 0 12px; font-size: 14px; font-weight: 600; }
.lesson-variants > div { text-align: center; }
.lesson-down { margin: 8px auto; color: #75839a; }
.lesson-server-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.lesson-diagram figcaption { margin-top: 12px; font-size: 12px; color: #65738a; text-align: center; }
.lesson-source { display: inline-flex; align-items: center; gap: 6px; color: #4054c7; font-size: 13px; text-decoration: underline; text-underline-offset: 3px; }
.lesson-source:hover { color: #263a9a; }
.inspector-learn { margin-top: 24px; padding-top: 16px; border-top: 1px solid #e7ebf2; }
.inspector-learn button { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 12px; border: 1px solid #dce3ee; border-radius: 6px; background: #fff; color: #405078; font: inherit; font-size: 13px; font-weight: 500; text-align: left; cursor: pointer; }
.inspector-learn button svg { flex-shrink: 0; color: #5361cb; }
.inspector-learn button + button { margin-top: 8px; }
.api-request-flow { display: grid; justify-items: center; gap: 8px; }
.api-request-flow .lesson-node { width: min(100%, 320px); box-sizing: border-box; }
.inspector-learn button:hover { background: #f5f7ff; border-color: #b7c1f2; }
.lesson-takeaway { border-left: 3px solid #d59832; padding-left: 12px; }
.lesson-navigation { position: sticky; bottom: -24px; background: white; padding: 16px 0; display: flex; align-items: center; justify-content: space-between; margin-top: 20px; }
.lesson-navigation { border-top: 1px solid #e7ebf2; font-size: 13px; color: #65738a; }
.lesson-navigation button, .lesson-close { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; border: 1px solid transparent; border-radius: 8px; background: #f1f4fa; color: #44577b; cursor: pointer; transition: background 120ms ease; }
.lesson-navigation button:hover:not(:disabled), .lesson-close:hover { background: #e7ecfa; color: #3548b5; }
.lesson-navigation button:disabled { opacity: .35; cursor: default; }
.lesson-close { background: transparent; }
@media (max-width: 480px) {
  dialog.lesson-dialog { padding: 20px; }
  .lesson-variants { gap: 12px; }
  .lesson-server-pair { gap: 4px; }
  .lesson-exchange { gap: 8px; grid-template-columns: minmax(0, 1fr) 88px minmax(0, 1fr); }
  .lesson-node { font-size: 12px; }
  .lesson-body h3 { font-size: 22px; }
}

/* Selected connectors expose the library's native endpoint drag targets. */
.react-flow__edgeupdater {
  fill: #fff;
  stroke: #6573df;
  stroke-width: 2;
  cursor: grab;
}
.react-flow__edgeupdater:hover {
  fill: #e9ecff;
}
.react-flow__edgeupdater:active {
  cursor: grabbing;
}

assets.src/learn/database-lessons.css:
.database-flow { display: grid; gap: 10px; justify-items: center; }
.database-flow-step { display: grid; gap: 10px; justify-items: center; width: min(100%, 340px); }
.database-flow-step .lesson-node { box-sizing: border-box; width: 100%; min-height: 52px; }
.database-flow-step > svg { width: 18px; height: 18px; color: #7a88a0; }
.database-split { display: grid; grid-template-columns: minmax(0, 1fr) minmax(90px, .9fr) minmax(0, 1fr); gap: 12px; align-items: center; }
.database-split figcaption { grid-column: 1 / -1; }
.database-partition { display: grid; justify-items: center; gap: 8px; text-align: center; color: #8a4c3a; font-size: 12px; }
.database-partition > span[aria-hidden] { font-size: 28px; }
.database-partition small { color: #65738a; font-weight: 400; }
.database-records { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.database-records h4, .database-query-models h4 { margin: 0 0 12px; font-size: 14px; }
.database-records table { width: 100%; border-collapse: collapse; margin-bottom: 12px; font-size: 12px; }
.database-records caption { text-align: left; color: #56657b; padding-bottom: 5px; }
.database-records td, .database-records th { padding: 7px; text-align: left; border: 1px solid #dce3ee; }
.database-records th { background: #f3f6fa; }
.database-records figcaption { grid-column: 1 / -1; }
.database-records > div { min-width: 0; }
.database-records pre, .database-sql { margin: 0; padding: 14px; border: 1px solid #dce3ee; background: #f8fafc; border-radius: 6px; white-space: pre-wrap; overflow-wrap: anywhere; font-size: 12px; line-height: 1.7; }
.lesson-dialog .database-records p, .lesson-dialog .database-query-models p { font-size: 12px; color: #65738a; }
.database-query-models { display: grid; gap: 18px; }
.database-query-models > div + div { border-top: 1px solid #e5e9f0; padding-top: 18px; }
.database-query-models code { font-size: 12px; overflow-wrap: anywhere; }
.database-query-models p { margin: 8px 0 0; }
.database-capabilities { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; text-align: center; font-size: 12px; color: #586781; }
.database-tradeoffs { display: grid; gap: 14px; }
.database-tradeoffs > div { display: grid; grid-template-columns: 1fr 20px 1fr; gap: 8px; align-items: center; font-size: 13px; color: #586781; }
.database-tradeoffs strong { grid-column: 1 / -1; font-weight: 600; color: #303c50; }
.database-tradeoffs > div + div { border-top: 1px solid #e5e9f0; padding-top: 14px; }
.database-tradeoffs svg { width: 16px; height: 16px; }
.database-rules { display: flex; gap: 20px; align-items: start; }
.database-rules > svg { flex-shrink: 0; color: #38816b; }
.database-rules dl { margin: 0; font-size: 13px; }
.database-rules dt { font-family: monospace; color: #4054c7; }
.database-rules dd { margin: 4px 0 16px; color: #586781; }
.database-transaction { border: 1px dashed #389478; padding: 18px; display: grid; justify-items: center; gap: 16px; text-align: center; font-size: 13px; }
.database-transaction > small { color: #38816b; }
.database-transaction > div { display: flex; align-items: center; justify-content: center; gap: 12px; flex-wrap: wrap; }
.database-acid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 0; font-size: 12px; }
.database-acid dt { font-weight: 600; }
.database-acid dd { margin: 5px 0 0; color: #586781; }
.database-outcomes { margin-top: 16px; }
@media (max-width: 480px) {
  .database-records { grid-template-columns: 1fr; }
  .database-split { gap: 6px; grid-template-columns: minmax(0, 1fr) 84px minmax(0, 1fr); }
  .database-capabilities { grid-template-columns: 1fr; }
  .database-transaction { padding: 14px 8px; }
}
